      "achados": [
        {
          "proposicao": "A fonte descreve que, no contexto resumido da Bacia de Campos, havia helicópteros entre os recursos logísticos de apoio às operações offshore, incluindo um dedicado exclusivamente ao resgate médico.",
          "trechos": [
            "Ed7b734afbfa5e20d:700:1393"
          ],
          "condicoes": [
            "descrição contextual do arranjo logístico regional apresentada pelo texto"
