      "achados": [
        {
          "proposicao": "A fonte apresenta 'helideck' como o andar do heliponto com pista de pouso e decolagem de helicópteros, contribuindo apenas com definição terminológica básica.",
          "trechos": [
            "Ec69159bd8db9b8df:1395:2093"
          ],
          "condicoes": [
            "uso como glossário no documento compilado"
          ],
          "limites": [
            "não há critérios de operação, segurança, compatibilidade, passageiros, manifestos ou evacuação médica",
            "por ser trecho glossarial, sua utilidade didática para o recorte é restrita"
          ]
        }
